bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec "$cid" node --input-type=module -e '
import {buildFreeAlbumRequest} from "/opt/videobot/src/telegram/freeAlbum.mjs";
import {buildPaidMediaRequest} from "/opt/videobot/src/telegram/paidMedia.mjs";
const a=buildFreeAlbumRequest({chatId:-1002373696859,messageThreadId:111,thumbnailFileId:"photo001",sampleFileId:"sample001"});
const p=buildPaidMediaRequest({chatId:-1002373696859,messageThreadId:111,mediaFileId:"main001",priceStars:10,payload:"sale001:1"});
if(a.media.length!==2||a.media[0].type!=="photo"||a.media[1].type!=="video"||!a.media.every(m=>m.has_spoiler===true))process.exit(63);
if(p.star_count!==10||p.media[0].type!=="video"||p.message_thread_id!==111)process.exit(64);
' || exit 65
docker exec "$cid" sh -c 'grep -q "sendMediaGroup" /opt/videobot/src/telegram/paidListingPublisher.mjs && grep -q "sendPaidMedia" /opt/videobot/src/telegram/paidListingPublisher.mjs' || exit 66
echo NATIVE_PAID_AND_FREE_ALBUM_LIVE_SOURCE=PASS
